// ============================================================
// src/api/matchesApi.js
// HTTP client for the PHP backend.
//
// BASE_URL points to your backend folder.
// XAMPP/WAMP dev:  http://localhost/valorant-tracker-final/backend
// Production:      https://yourdomain.com/backend
//
// Set REACT_APP_API_URL in your .env to override.
// ============================================================

const BASE    = process.env.REACT_APP_API_URL || 'http://localhost/valorant-tracker-final/backend';
const TEAM_ID = process.env.REACT_APP_TEAM_ID || 'aaaaaaaa-0000-0000-0000-000000000001';

async function request(url, options = {}) {
  const method = (options.method || 'GET').toUpperCase();
  const hasBody = options.body !== undefined && options.body !== null;
  const headers = {
    ...(hasBody || method !== 'GET' ? { 'Content-Type': 'application/json' } : {}),
    ...(options.headers || {}),
  };

  const res  = await fetch(url, {
    ...options,
    headers,
  });
  const json = await res.json();
  if (!json.success) throw new Error(json.error || 'API error');
  return json.data;
}

export const matchesApi = {
  getAll: async (filters = {}) => {
    const params = new URLSearchParams({ team_id: TEAM_ID });
    if (filters.map      && filters.map      !== 'All') params.set('map',      filters.map);
    if (filters.type     && filters.type     !== 'All') params.set('type',     filters.type);
    if (filters.opponent && filters.opponent !== '')    params.set('opponent', filters.opponent);
    return request(`${BASE}/api/matches.php?${params}`);
  },
  getById: async (id)    => request(`${BASE}/api/matches.php?id=${id}`),
  create:  async (match) => request(`${BASE}/api/matches.php`, {
    method: 'POST',
    body:   JSON.stringify({ ...match, team_id: TEAM_ID }),
  }),
  update: async (match)  => request(`${BASE}/api/matches.php?id=${match.id}`, {
    method: 'PUT',
    body:   JSON.stringify(match),
  }),
  remove: async (id)     => request(`${BASE}/api/matches.php?id=${id}`, { method: 'DELETE' }),
};

export const playersApi = {
  getAll:  async ()       => request(`${BASE}/api/players.php?team_id=${TEAM_ID}`),
  getById: async (id)     => request(`${BASE}/api/players.php?id=${id}`),
  create:  async (player) => request(`${BASE}/api/players.php`, {
    method: 'POST',
    body:   JSON.stringify({ ...player, team_id: TEAM_ID }),
  }),
  update:  async (player) => request(`${BASE}/api/players.php?id=${player.id}`, {
    method: 'PUT',
    body:   JSON.stringify(player),
  }),
};

export const statsApi = {
  mapWinrates:    async () => request(`${BASE}/api/stats.php?type=map_winrates&team_id=${TEAM_ID}`),
  agentStats:     async () => request(`${BASE}/api/stats.php?type=agent_stats&team_id=${TEAM_ID}`),
  teamEconomics:  async () => request(`${BASE}/api/stats.php?type=team_economics&team_id=${TEAM_ID}`),
  playerAverages: async () => request(`${BASE}/api/stats.php?type=player_averages&team_id=${TEAM_ID}`),
};

export const aiApi = {
  /**
   * Upload a file to the backend for Gemini AI extraction.
   * @param {File} file
   * @param {'Scrim'|'Tournament'} matchType
   * @returns {Promise<{extracted: object, raw: string}>}
   */
  extract: async (file, matchType) => {
    const formData = new FormData();
    formData.append('file', file);
    formData.append('type', matchType);

    let res;
    try {
      res = await fetch(`${BASE}/api/ai_extract.php`, {
        method: 'POST',
        body: formData,
      });
    } catch (err) {
      throw new Error(`AI request failed: ${err?.message || 'Network/CORS error'}`);
    }

    const raw = await res.text();
    let json = null;
    try {
      json = raw ? JSON.parse(raw) : null;
    } catch (_) {
      // Keep fallback below for non-JSON upstream errors.
    }

    if (!res.ok) {
      const msg = json?.error || `AI extraction failed (${res.status})`;
      throw new Error(msg);
    }
    if (!json?.success) {
      throw new Error(json?.error || 'AI extraction failed');
    }
    return json.data;
  },
};

export const referenceApi = {
  maps:      async () => request(`${BASE}/api/reference.php?type=maps`),
  agents:    async () => request(`${BASE}/api/reference.php?type=agents`),
  opponents: async () => request(`${BASE}/api/reference.php?type=opponents&team_id=${TEAM_ID}`),
};
